import urllib.request
import json

# Check beancount acme bank files
for fname in ['acmebank1.pdf.extract', 'acmebank1.pdf.file_account']:
    url = f'https://raw.githubusercontent.com/beancount/beancount/master/examples/ingest/office/importers/acme/{fname}'
    try:
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
        resp = urllib.request.urlopen(req, timeout=10)
        print(f'{fname}:')
        print(resp.read().decode()[:2000])
        print('---')
    except Exception as e:
        print(f'{fname} error: {e}')

